static QJsonObject properties(GmatBase &object){QJsonObject p;for(const auto &f:resourceProperties(object))p[f.name]=f.value;if(object.GetTypeName()=="Variable")p["Value"]=QString::number(object.GetRealParameter("Value"),'g',17);if(object.GetTypeName()=="String")p["Value"]=QString::fromStdString(object.GetStringParameter("Value"));require(!p.isEmpty(),"Save property inventory empty");return p;}
static bool equivalent(const QString &a,const QString &b){if(a==b)return true;bool x=false,y=false;double av=a.toDouble(&x),bv=b.toDouble(&y);return x&&y&&std::isfinite(av)&&std::isfinite(bv)&&std::abs(av-bv)<=1e-11*std::max(1.,std::abs(av));}
